      // Verified Official Services (Dhawalpuri & Maharashtra)
      'gs_income_name': 'Income Certificate (उत्पन्न दाखला)',
      'gs_income_exp': 'Official certification proving an individual\'s annual family income from all sources for government subsidies and educational fee concessions.',
      'gs_income_elig': 'All residents of Dhawalpuri requiring income proof for educational admissions, scholarships, or government scheme eligibility.',
      'gs_income_dept': 'Revenue Department, Government of Maharashtra',
      'gs_income_method': 'Online via Aaple Sarkar portal or offline at Setu Suvidha Kendra / Tahsil Office Parner.',
      'gs_income_fees': 'Statutory fee of ₹33.60 at Setu/CSC, or standard portal processing charge.',
      'gs_income_time': '15 working days (Under Maharashtra Right to Public Services Act).',

      'gs_caste_name': 'Caste Certificate (जातीचा दाखला)',
      'gs_caste_exp': 'Official certification validating an individual\'s caste category for educational reservations, scholarships, and statutory government welfare benefits.',
      'gs_caste_elig': 'Permanent residents of Maharashtra belonging to SC, ST, VJNT, OBC, or SBC categories with valid genealogical lineage records.',
      'gs_caste_dept': 'Revenue Department & Sub-Divisional Officer (SDO)',
      'gs_caste_method': 'Online application through Aaple Sarkar portal or submission at Parner Sub-Divisional Office.',
      'gs_caste_fees': 'Standard nominal statutory fee (approx ₹45 - ₹60).',
      'gs_caste_time': '21 to 45 working days depending on verification process.',

      'gs_712_name': 'Digital 7/12 & 8A Land Extract (डिजिटल सातबारा)',
      'gs_712_exp': 'Legally valid digitally signed record of agricultural land rights, survey number details, ownership shares, crop entries, and bank loan liabilities.',
      'gs_712_elig': 'Agricultural landholders and farmers owning land within Dhawalpuri village revenue boundaries.',
      'gs_712_dept': 'Revenue Department & Settlement Commissioner, Maharashtra',
      'gs_712_method': 'Instant online download from Digital Satbara portal, or unverified extract view on Mahabhulekh.',
      'gs_712_fees': 'Free to view on Mahabhulekh; ₹15 per digitally signed legal extract copy.',
      'gs_712_time': 'Instant online download (24x7).',

      'gs_pmkisan_name': 'PM-KISAN Samman Nidhi (पीएम किसान)',
      'gs_pmkisan_exp': 'Central government direct benefit transfer providing ₹6,000 annually in three equal installments of ₹2,000 directly into farmers\' Aadhaar-seeded bank accounts.',
      'gs_pmkisan_elig': 'All landholding farmer families in Dhawalpuri with cultivable agricultural land registered in their name (subject to exclusion criteria).',
      'gs_pmkisan_dept': 'Department of Agriculture & Farmers Welfare, Govt. of India',
      'gs_pmkisan_method': 'Online farmer self-registration and e-KYC on PM-Kisan portal or through local Common Service Centers (CSC).',
      'gs_pmkisan_fees': 'Free of cost on portal; nominal service charge for biometric e-KYC at CSC.',
      'gs_pmkisan_time': 'Subject to district agriculture officer verification and PFMS payment cycle.',

      'gs_ayushman_name': 'Ayushman Bharat (PM-JAY) & MJPJAY Health Card',
      'gs_ayushman_exp': 'Free cashless secondary and tertiary hospital treatment up to ₹5 Lakh per family per year across empaneled public and private hospitals.',
      'gs_ayushman_elig': 'Eligible families under SECC 2011 database, Ration Card holders (Yellow and Orange), and Maharashtra health coverage expansion.',
      'gs_ayushman_dept': 'State Health Assurance Society (SHAS), Maharashtra & National Health Authority',
      'gs_ayushman_method': 'E-KYC and Ayushman Card generation via Ayushman Beneficiary Portal, Setu Kendra, or Dhawalpuri PHC Sub-Center.',
      'gs_ayushman_fees': 'Completely free of cost.',
      'gs_ayushman_time': 'Card issued within 24 to 48 hours upon biometric/OTP verification.',

      'gs_mahadbt_name': 'MahaDBT Post-Matric & Pre-Matric Scholarships',
      'gs_mahadbt_exp': 'State government scholarships, tuition fee reimbursements, exam fee concessions, and hostel maintenance allowances for higher secondary and collegiate education.',
      'gs_mahadbt_elig': 'Students from SC, ST, OBC, VJNT, EWS, and minority categories enrolled in recognized schools and colleges with family income below statutory limits.',
      'gs_mahadbt_dept': 'Social Justice & Special Assistance Department, Govt. of Maharashtra',
      'gs_mahadbt_method': 'Online application and document submission via MahaDBT Mahaswayam portal.',
      'gs_mahadbt_fees': 'Free of cost.',
      'gs_mahadbt_time': 'Processed according to academic admission and disbursement schedules.',

      'gs_sanjay_gandhi_name': 'Sanjay Gandhi Niradhar Pension Yojana',
      'gs_sanjay_gandhi_exp': 'Monthly financial pension of ₹1,500 for destitute persons, elderly individuals, widows, and severely disabled rural villagers.',
      'gs_sanjay_gandhi_elig': 'Residents of Dhawalpuri aged 65 or above, destitute persons with family income under ₹21,000/year, or persons with 40%+ disability.',
      'gs_sanjay_gandhi_dept': 'Social Justice & Special Assistance Department / Tahsil Office Parner',
      'gs_sanjay_gandhi_method': 'Physical application submitted to the Sanjay Gandhi Scheme Committee at Tahsil Office, Parner.',
      'gs_sanjay_gandhi_fees': 'Free application form.',
      'gs_sanjay_gandhi_time': 'Approved quarterly during Tahsil Sanjay Gandhi Committee meetings.',

