      'news1_headline': 'Solar Powered Water Pumping Project Approved for Dhawalpuri Wards',
      'news1_summary': 'Parner Taluka Administration approves installation of 3 solar pump sets to ensure continuous drinking water supply in high-altitude wadis of Dhawalpuri.',
      'news1_body': 'Under the rural renewable energy and drinking water infrastructure initiative, Parner Panchayat Samiti and Dhawalpuri Gram Panchayat have secured approval for a dedicated solar-powered water lifting scheme.\\n\\nThe project addresses chronic seasonal water pressure drops experienced by households in Maruti Galli, Malwadi, and Khandoba Vasti. The installation will feature three 5-horsepower solar submersible pumps connected to the existing community cistern.\\n\\nGram Panchayat officials confirmed that work will commence next month following the technical inspection by MSEDCL and water supply engineers. The initiative is expected to reduce village pumping electricity expenses by nearly 40%.',
      'news1_author': 'Kishor Gholap (Gram Vikas Correspondent)',
      'news1_publisher': 'Dhawalpuri Gram Samachar',
      'news2_headline': 'Kharif Season Organic Fertilizer Distribution at Sub-Centre',
      'news2_summary': 'Taluka Agriculture Department distributes subsidized bio-fertilizers and soil health testing cards to over 150 local farmers in Dhawalpuri.',
      'news2_body': 'The Parner Krishi Vibhag, in collaboration with the Dhawalpuri Shetkari Bachat Gat, completed a two-day distribution shibir at the village agricultural sub-centre.\\n\\nOver 150 farmers received soil health testing cards along with subsidized bio-fertilizers including Trichoderma and Rhizobium cultures suitable for local bajra and onion crops. Agriculture extension officers conducted live demonstrations on organic compost enrichment.\\n\\nFarmers were encouraged to register on the national portal to access forthcoming micro-irrigation subsidies for the upcoming post-monsoon planting season.',
      'news2_author': 'Santosh Gawade (Agronomy Associate)',
      'news2_publisher': 'Krishi Varta Parner',
      'news3_headline': 'ZP Primary School Dhawalpuri Students Win Taluka-Level Science Quiz',
      'news3_summary': 'Class 7 students from Dhawalpuri secured first place in the Parner Taluka Rural Science and Innovation Exhibition for their drip-irrigation model.',
      'news3_body': 'Students of Zilla Parishad Primary School Dhawalpuri brought pride to the village by bagging the first prize in the Parner Taluka Rural Science Fair held in Parner town.\\n\\nGuided by science teacher Shri Darekar, the team consisting of Aarav Thube and Sneha Shinde demonstrated an automated moisture-sensor drip irrigation system crafted using repurposed electronic components and local soil sensors.\\n\\nThe project was selected to represent Parner Taluka at the District Science Exhibition in Ahilyanagar next month. The School Management Committee and Gram Panchayat congratulated the students and announced an educational merit grant.',
      'news3_author': 'Sunita Shinde (Education Correspondent)',
      'news3_publisher': 'Dhawalpuri Shikshan Samvad',
      'news4_headline': 'Gram Sabha Passes Cleanliness & Plastic-Free Dhawalpuri Resolution',
      'news4_summary': 'Special Gram Sabha under Sarpanch chairmanship resolves strict ban on single-use plastics and introduces door-to-door waste segregation.',
      'news4_body': 'A well-attended special Gram Sabha convened at the Dhawalpuri Gram Panchayat Bhavan with active participation from village residents, youth mandals, and women self-help groups.\\n\\nThe assembly passed an unanimous resolution declaring Dhawalpuri single-use plastic free starting next month. The Gram Panchayat will distribute cloth bags to village shops and deploy a tractor-based segregated waste collection system covering all main wards and weekly market areas.\\n\\nSarpanch Ramesh Thube urged all shopkeepers, onion traders, and households to support the cleanliness drive to make Dhawalpuri a model green village in Parner taluka.',
      'news4_author': 'Gram Panchayat Media Cell',
      'news4_publisher': 'Dhawalpuri Panchayat Records',
      'news5_headline': 'Free Health Checkup & Eye Screening Camp at Primary Health Centre',
      'news5_summary': 'Over 220 residents screened for hypertension, diabetes, and cataracts; free medicines and spectacles distributed to senior citizens.',
      'news5_body': 'A comprehensive health diagnosis and treatment camp was organized at the Dhawalpuri Primary Health Centre by visiting medical specialists from Ahilyanagar Civil Hospital and Parner Rural Hospital.\\n\\nA total of 226 village residents underwent general medical examinations, ECG screenings, and vision tests. Thirty-eight elderly patients diagnosed with cataracts were referred for free surgical procedures with transportation arranged by the local committee.\\n\\nMedical Officer Dr. Kulkarni announced that monthly follow-up OPDs will continue on the first Thursday of every month at the Dhawalpuri PHC.',
      'news5_author': 'Dr. S. Kulkarni (PHC Medical Officer)',
      'news5_publisher': 'Parner Arogya Patrika',
      'news6_headline': 'Historic Temple Architectural Stone Inscriptions Documented in Dhawalpuri',
      'news6_summary': 'Heritage researchers document historic stone carvings and water stepwells near the Old Temple complex to preserve village heritage.',
      'news6_body': 'A heritage documentation team visited Dhawalpuri to study and photograph medieval stone carvings, hero stones (Veergals), and ancient water retention stepwells situated near the old village boundary.\\n\\nLocal elders guided the researchers through historical landmarks dating back several centuries, sharing oral folklore and pilgrimage traditions associated with the village.\\n\\nA summary report highlighting the historical significance of Dhawalpuri architecture will be compiled for the Maharashtra Archaeological Heritage Register to support future preservation and village tourism awareness.',
      'news6_author': 'Prof. V. Deshmukh (Heritage Historian)',
      'news6_publisher': 'Maharashtra Heritage Forum',
      'news_report_issue': 'Report Incorrect Info',
      'news_report_title': 'Report Incorrect Information',
      'news_issue_other': 'Other issue',
      'news_report_success': 'Thank you! Your feedback has been recorded for editorial review.',

