      // Mock Notice 1: Water Supply
      'n1_title': 'पाणी पुरवठा बंद राहील (रविवार)',
      'n1_summary': 'पाईपलाईन दुरुस्तीसाठी रविवारी सकाळी वॉर्ड १ आणि २ चा पाणी पुरवठा बंद राहील.',
      'n1_desc': 'सर्व ग्रामस्थांना कळविण्यात येते की, वॉर्ड क्र. १ (पेठ भाग) आणि वॉर्ड क्र. २ (विकास नगर) मधील सार्वजनिक पाणीपुरवठा रविवार, ५ सप्टेंबर रोजी सकाळी ६:०० ते ११:०० या वेळेत तात्पुरता बंद राहील. जलकुंभाजवळील मुख्य जलवाहिनीच्या तातडीच्या दुरुस्तीच्या कामासाठी हा बंद आवश्यक आहे. कृपया ग्रामस्थांनी आवश्यक पाण्याचा साठा आधीच करून ठेवावा.',
      'n1_source': 'ग्रामपंचायत पाणी पुरवठा विभाग',
      
      // Mock Notice 2: Electricity
      'n2_title': 'नियोजित वीज पुरवठा खंडित',
      'n2_summary': 'या शुक्रवारी सकाळी १० ते दुपारी २ या वेळेत महावितरणद्वारे देखभाल दुरुस्ती काम.',
      'n2_desc': 'महाराष्ट्र राज्य विद्युत वितरण कंपनी (महावितरण) कडून शुक्रवार, ३ सप्टेंबर रोजी सकाळी १०:०० ते दुपारी २:०० या वेळेत वीज पुरवठा खंडित ठेवण्यात येणार आहे. उच्च दाब वाहिन्यांजवळील झाडांच्या फांद्या छाटणे आणि सबस्टेशन ट्रान्सफॉर्मरची दुरुस्ती करण्यासाठी हा बंद घोषित करण्यात आला आहे. गैरसोयीबद्दल दिलगीर आहोत.',
      'n2_source': 'महावितरण कार्यालय',

      // Mock Notice 3: Agriculture
      'n3_title': 'अनुदानित बियाणे वाटप योजना',
      'n3_summary': 'शेतकऱ्यांनी १ सप्टेंबरपासून कृषी सेवा केंद्रातून अनुदानित बियाणे जमा करावे.',
      'n3_desc': 'कृषी विभागातर्फे रब्बी हंगामासाठी अनुदानित बियाणे वाटप योजना सुरू झाली आहे. गहू, मोहरी आणि भाजीपाल्याचे अनुदानित बियाणे १ सप्टेंबरपासून स्थानिक शेतकऱ्यांना दिले जाईल. शेतकऱ्यांनी येताना आधार कार्ड, माती परीक्षण कार्ड आणि ७/१२ उतारा सोबत कृषी सेवा केंद्रात आणावा.',
      'n3_source': 'कृषी कार्यालय',

      // Mock Notice 4: Emergency
      'n4_title': 'अतिवृष्टीचा इशारा व सतर्कतेचा आदेश',
      'n4_summary': 'हवामान खात्याकडून रेड अलर्ट जारी. पुढील २४ तास घरातच राहावे.',
      'n4_desc': 'जिल्हा आपत्ती व्यवस्थापन प्राधिकरणाने पुढील २४ तासांसाठी हवामानाचा अतिदक्षतेचा इशारा (रेड अलर्ट) जारी केला आहे. अहिल्यानगर जिल्ह्यात जोरदार वाऱ्यासह मुसळधार ते अतिमुसळधार पाऊस पडण्याची शक्यता आहे. नागरिकांनी विनाकारण घराबाहेर पडू नये, नद्या आणि ओढ्यांजवळ जाणे टाळावे.',
      'n4_source': 'जिल्हाधिकारी कार्यालय प्रशासन',

      // Mock Notice 5: Government
      'n5_title': 'मोफत आरोग्य तपासणी शिबिर',
      'n5_summary': 'प्राथमिक आरोग्य केंद्राद्वारे जिल्हा परिषद शाळा आवारात भव्य शिबिर.',
      'n5_desc': 'रविवार, ६ सप्टेंबर रोजी सकाळी ९:०० ते दुपारी ४:०० या वेळेत जि. प. प्राथमिक शाळा आवारात सर्व ग्रामस्थांसाठी मोफत बहुउद्देशीय आरोग्य तपासणी शिबिर आयोजित केले आहे. यामध्ये बालरोग, हृदयरोग आणि स्त्रीरोग तज्ज्ञ मोफत तपासणी करतील. मोफत औषधेही दिली जातील.',
      'n5_source': 'प्राथमिक आरोग्य केंद्र (PHC)',

      // Mock Notice 6: Education
      'n6_title': 'शिष्यवृत्ती अर्ज प्रक्रिया सुरू',
      'n6_summary': 'इयत्ता ५ वी ते १० वी मधील विद्यार्थ्यांचे शिष्यवृत्ती अर्ज १५ सप्टेंबरपर्यंत सादर करा.',
      'n6_desc': 'इयत्ता ५ वी ते १० वी मध्ये शिकणाऱ्या विद्यार्थ्यांना सूचित करण्यात येते की, शैक्षणिक वर्ष २०२६-२७ साठी मॅट्रिकपूर्व शिष्यवृत्तीचे अर्ज सुरू झाले आहेत. ग्रामपंचायत डिजिटल केंद्रात ऑनलाईन अर्ज विनामूल्य सादर केले जाऊ शकतात. आवश्यक कागदपत्रे: मागील वर्षाचे गुणपत्रक, जातीचा दाखला आणि पालकांचा उत्पन्नाचा दाखला.',
      'n6_source': 'जि. प. हायस्कूल मुख्याध्यापक',

      // Mock Notice 7: Events
      'n7_title': 'ग्रामसभा बैठकीची सूचना',
      'n7_summary': 'शनिवार ५ सप्टेंबर रोजी सकाळी १० वाजता पंचायत सभागृहात मासिक ग्रामसभा.',
      'n7_desc': 'कळविण्यात येते की, शनिवार, ५ सप्टेंबर रोजी सकाळी १०:०० वाजता ग्रामपंचायत सभागृहात मासिक ग्रामसभेचे आयोजन करण्यात आले आहे. विषय सूची: १. पावसाळी स्वच्छता आराखडा मंजूर करणे. २. रस्त्यांच्या दुरुस्तीसाठी निधी वाटप. ३. नवीन रेशन कार्ड अर्जांची पडताळणी. सर्व ग्रामस्थांनी वेळेवर उपस्थित राहावे.',
      'n7_source': 'सरपंच / ग्रामसेवक कार्यालय',

