      'publisher_label': 'प्रकाशक',
      'source_link_label': 'मूळ स्रोत दुवा',
      'related_places_label': 'संबंधित ठिकाणे',
      'published_on': 'प्रसिद्ध दिनांक',
      'updated_on': 'अद्ययावत दिनांक',
      'read_time': 'मिनिटे वाचन वेळ',
      'news1_headline': 'ढवळपुरीतील विविध वाड्यांसाठी सौरऊर्जा पाणी उपसा योजना मंजूर',
      'news1_summary': 'पारनेर तालुका प्रशासनाकडून ढवळपुरीतील उंचावरील वाड्यांमध्ये सुरळीत पिण्याच्या पाण्यासाठी ३ सौर पंप संच बसविण्यास मंजुरी.',
      'news1_body': 'ग्रामीण नवीकरणीय ऊर्जा आणि पेयजल पायाभूत सुविधा उपक्रमांतर्गत, पारनेर पंचायत समिती व ढवळपुरी ग्रामपंचायतीच्या प्रयत्नांना यश आले असून स्वतंत्र सौर पाणी उपसा योजनेस मंजुरी मिळाली आहे.\\n\\nमारुती गल्ली, माळवाडी आणि खंडोबा वस्ती या उंचावरील भागातील नागरिकांना उन्हाळ्यात येणाऱ्या पाणी टंचाईवर हा प्रकल्प कायमस्वरूपी तोडगा ठरेल. यामध्ये विद्यमान पाण्याच्या टाकीस जोडलेले तीन ५-अश्वशक्तीचे सौर पंप बसविले जातील.\\n\\nमहावितरण व पाणीपुरवठा विभागाच्या तांत्रिक तपासणीनंतर पुढील महिन्यात प्रत्यक्ष कामास सुरुवात होईल, असे ग्रामपंचायतीकडून सांगण्यात आले. यामुळे गावाचा पंपिंगचा वीज खर्च सुमारे ४० टक्क्यांनी कमी होईल.',
      'news1_author': 'किशोर घोलप (ग्राम विकास वार्ताहर)',
      'news1_publisher': 'ढवळपुरी ग्राम समाचार',
      'news2_headline': 'खरीप हंगामासाठी ढवळपुरी उपकेंद्रात सेंद्रिय खत व बियाणे वाटप',
      'news2_summary': 'तालुका कृषी विभागातर्फे ढवळपुरीतील १५० हून अधिक शेतकऱ्यांना सवलतीच्या दरात सेंद्रिय खते आणि मृदा आरोग्य पत्रिका वाटप.',
      'news2_body': 'पारनेर कृषी विभाग आणि ढवळपुरी शेतकरी बचत गटाच्या संयुक्त विद्यमाने गावातील कृषी उपकेंद्रात दोन दिवसीय खत वाटप शिबिर यशस्वीरीत्या पार पडले.\\n\\nया शिबिरात बाजरी व कांदा पिकासाठी उपयुक्त ट्रायकोडर्मा, रायझोबियम यांसारखी जिवाणू खते सवलतीत देण्यात आली. तसेच १५० हून अधिक शेतकऱ्यांना मृदा आरोग्य पत्रिका वितरित करण्यात आल्या. कृषी अधिकाऱ्यांनी सेंद्रिय खत निर्मितीचे प्रात्यक्षिक दाखवले.\\n\\nआगामी खरीप व रब्बी हंगामासाठी सूक्ष्म सिंचन अनुदानाचा लाभ घेण्यासाठी शेतकऱ्यांनी महाडीबीटी पोर्टलवर नोंदणी करण्याचे आवाहन करण्यात आले आहे.',
      'news2_author': 'संतोष गावडे (कृषी सहाय्यक)',
      'news2_publisher': 'कृषी वार्ता पारनेर',
      'news3_headline': 'जिल्हा परिषद प्राथमिक शाळा ढवळपुरीच्या विद्यार्थ्यांची तालुका विज्ञान स्पर्धेत बाजी',
      'news3_summary': 'ठिबक सिंचन मॉडेल सादर करणाऱ्या ढवळपुरी शाळेतील इयत्ता ७ वीच्या विद्यार्थ्यांनी पारनेर तालुका विज्ञान प्रदर्शनात प्रथम क्रमांक पटकावला.',
      'news3_body': 'पारनेर येथे आयोजित तालुकास्तरीय ग्रामीण विज्ञान आणि नवोपक्रम प्रदर्शनात जिल्हा परिषद प्राथमिक शाळा ढवळपुरीच्या विद्यार्थ्यांनी प्रथम क्रमांक मिळवून गावाचा नावलौकिक वाढवला.\\n\\nविज्ञान शिक्षक श्री. दरेकर यांच्या मार्गदर्शनाखाली इयत्ता ७ वीतील आरव ठुबे व स्नेहा शिंदे यांनी स्वयंचलित सॉईल-मॉइश्चर सेन्सरवर आधारित ठिबक सिंचन प्रणालीचे कार्यक्षम मॉडेल सादर केले.\\n\\nया प्रकल्पाची निवड पुढील महिन्यात अहिल्यानगर येथे होणाऱ्या जिल्हा विज्ञान प्रदर्शनासाठी झाली आहे. शाळा व्यवस्थापन समिती व ग्रामपंचायतीने यशस्वी विद्यार्थ्यांचे अभिनंदन करून शैक्षणिक गौरव निधी जाहीर केला.',
      'news3_author': 'सुनिता शिंदे (शिक्षण वार्ताहर)',
      'news3_publisher': 'ढवळपुरी शिक्षण संवाद',
      'news4_headline': 'ग्रामसभेत स्वच्छ व प्लास्टिकमुक्त ढवळपुरीचा एकमुखी ठराव मंजूर',
      'news4_summary': 'सरपंचांच्या अध्यक्षतेखाली पार पडलेल्या विशेष ग्रामसभेत एकल-वापर प्लास्टिकवर बंदी आणि घंटागाडीद्वारे कचरा वर्गीकरणाचा निर्णय.',
      'news4_body': 'ढवळपुरी ग्रामपंचायत सभागृहात सरपंच यांच्या अध्यक्षतेखाली ग्रामस्थ, तरुण मंडळे व महिला बचत गटांच्या उपस्थितीत विशेष ग्रामसभा उत्साहात पार पडली.\\n\\nया सभेत पुढील महिन्यापासून ढवळपुरी गाव एकल-वापर प्लास्टिकमुक्त करण्याचा एकमुखाने ठराव मंजूर करण्यात आला. गावातील सर्व दुकानांमध्ये कापडी पिशव्यांचा वापर करण्याचे आवाहन करण्यात आले असून बाजारपेठ व वस्त्यांसाठी स्वतंत्र कचरा संकलन मोहीम सुरू केली जाईल.\\n\\nढवळपुरीला पारनेर तालुक्यातील आदर्श व हरित गाव बनविण्यासाठी सर्व ग्रामस्थांनी व कांदा व्यापाऱ्यांनी या मोहिमेत सहकार्य करण्याचे आवाहन सरपंच रमेश ठुबे यांनी केले.',
      'news4_author': 'ग्रामपंचायत जनसंपर्क कक्ष',
      'news4_publisher': 'ढवळपुरी ग्रामपंचायत अभिलेख',
      'news5_headline': 'ढवळपुरी प्राथमिक आरोग्य केंद्रात मोफत नेत्र तपासणी व आरोग्य शिबिर',
      'news5_summary': '२२० हून अधिक ग्रामस्थांची मोफत आरोग्य तपासणी; ज्येष्ठ नागरिकांना मोफत चष्मे व औषधांचे वाटप करण्यात आले.',
      'news5_body': 'अहिल्यानगर जिल्हा रुग्णालय आणि पारनेर ग्रामीण रुग्णालयाच्या सहकार्याने ढवळपुरी प्राथमिक आरोग्य केंद्रात सर्वसमावेशक मोफत आरोग्य तपासणी शिबिर संपन्न झाले.\\n\\nशिबिरामध्ये २२६ ग्रामस्थांची रक्तदाब, मधुमेह, हृदय तपासणी (ईसीजी) आणि नेत्र तपासणी करण्यात आली. मोतीबिंदू आढळलेल्या ३८ ज्येष्ठ नागरिकांवर मोफत शस्त्रक्रिया करण्यासाठी नावनोंदणी करण्यात आली असून वाहनाची सोय करण्यात आली आहे.\\n\\nवैद्यकीय अधिकारी डॉ. कुलकर्णी यांनी सांगितले की, दर महिन्याच्या पहिल्या गुरुवारी ढवळपुरी आरोग्य केंद्रात विशेष तपासणी ओपीडी सुरू राहील.',
      'news5_author': 'डॉ. एस. कुलकर्णी (वैद्यकीय अधिकारी)',
      'news5_publisher': 'पारनेर आरोग्य पत्रिका',
      'news6_headline': 'ढवळपुरातील पुरातन मंदिर स्थापत्य व शिलालेखांची नोंदणी पूर्ण',
      'news6_summary': 'गावाचा ऐतिहासिक वारसा जपण्यासाठी जुन्या मंदिर परिसरातील दगडी कोरीव काम आणि बारवांचे छायाचित्रण व दस्तऐवजीकरण.',
      'news6_body': 'ढवळपुरी गावच्या सीमेवरील मध्ययुगीन दगडी कोरीव काम, वीरगळ आणि पुरातन पायऱ्यांच्या बारवांचे दस्तऐवजीकरण करण्यासाठी इतिहास अभ्यासकांच्या पथकाने नुकतीच गावाला भेट दिली.\\n\\nगावातील ज्येष्ठ नागरिकांनी संशोधकांना प्राचीन मंदिरांचे ऐतिहासिक महत्त्व आणि मौखिक लोकपरंपरांची सविस्तर माहिती दिली.\\n\\nढवळपुरीचा हा गौरवशाली सांस्कृतिक वारसा जपण्यासाठी आणि ग्रामीण पर्यटनास चालना देण्यासाठी महाराष्ट्र पुरातत्व वारसा नोंदवहीत नोंद करण्याबाबत अहवाल तयार केला जात आहे.',
      'news6_author': 'प्रा. व्ही. देशमुख (इतिहास अभ्यासक)',
      'news6_publisher': 'महाराष्ट्र हेरिटेज मंच',
