      // Mock Notice 1: Water Supply
      'n1_title': 'जल आपूर्ति बंद रहेगी (रविवार)',
      'n1_summary': 'पाइपलाइन मरम्मत के कारण रविवार सुबह वार्ड 1 और 2 में पानी की आपूर्ति बंद रहेगी.',
      'n1_desc': 'सभी ग्रामीणों को सूचित किया जाता है कि वार्ड संख्या 1 (पेठ क्षेत्र) और वार्ड संख्या 2 (विकास नगर) में सार्वजनिक जलापूर्ति रविवार, 5 सितंबर को सुबह 6:00 बजे से 11:00 बजे तक अस्थायी रूप से बंद रहेगी. पानी की टंकी के पास मुख्य वितरण लाइन के त्वरित मरम्मत कार्य के लिए यह बंद आवश्यक है. कृपया आवश्यक पानी का भंडारण पहले से कर लें.',
      'n1_source': 'ग्राम पंचायत जलापूर्ति विभाग',
      
      // Mock Notice 2: Electricity
      'n2_title': 'निर्धारित बिजली कटौती की सूचना',
      'n2_summary': 'इस शुक्रवार सुबह 10 बजे से दोपहर 2 बजे तक महावितरण द्वारा रखरखाव का कार्य.',
      'n2_desc': 'महाराष्ट्र राज्य विद्युत वितरण कंपनी (महावितरण) द्वारा शुक्रवार, 3 सितंबर को सुबह 10:00 बजे से दोपहर 2:00 बजे तक बिजली कटौती की घोषणा की गई है. यह सबस्टेशन ट्रांसफार्मर की सर्विसिंग और पेड़ों की कटाई के काम के लिए आवश्यक है. असुविधा के लिए खेद है.',
      'n2_source': 'महावितरण कार्यालय',

      // Mock Notice 3: Agriculture
      'n3_title': 'अनुदानित बीज वितरण योजना',
      'n3_summary': 'किसान 1 सितंबर से कृषि सेवा केंद्र से अनुदानित बीज प्राप्त करें.',
      'n3_desc': 'कृषि विभाग द्वारा रबी सीजन के लिए अनुदानित बीज वितरण योजना शुरू की गई है. गेहूं, सरसों और सब्जियों के रियायती बीज 1 सितंबर से स्थानीय किसानों को वितरित किए जाएंगे. किसान अपने साथ आधार कार्ड, मिट्टी स्वास्थ्य कार्ड और 7/12 खतौनी दस्तावेज़ लेकर कृषि सेवा केंद्र पहुंचें.',
      'n3_source': 'कृषि कार्यालय',

      // Mock Notice 4: Emergency
      'n4_title': 'भारी बारिश की चेतावनी और अलर्ट',
      'n4_summary': 'मौसम विभाग द्वारा रेड अलर्ट जारी. अगले 24 घंटे घरों में ही रहें.',
      'n4_desc': 'जिला आपदा प्रबंधन प्राधिकरण ने अगले 24 घंटों के लिए भारी बारिश का रेड अलर्ट जारी किया है. अहिल्यानगर जिले में तेज हवाओं के साथ भारी से अति भारी बारिश की चेतावनी दी गई है. निवासियों को यात्रा करने से बचने, नदी-नालों से दूर रहने और पशुओं को सुरक्षित रखने की सलाह दी जाती है.',
      'n4_source': 'जिलाधिकारी कार्यालय प्रशासन',

      // Mock Notice 5: Government
      'n5_title': 'मुफ़्त स्वास्थ्य जाँच शिविर',
      'n5_summary': 'प्राथमिक स्वास्थ्य केंद्र द्वारा जिला परिषद स्कूल परिसर में विशाल शिविर.',
      'n5_desc': 'रविवार, 6 सितंबर को सुबह 9:00 बजे से दोपहर 4:00 बजे तक जि. प. प्राथमिक स्कूल परिसर में सभी ग्रामीणों के लिए निःशुल्क स्वास्थ्य जाँच शिविर का आयोजन किया गया है. इसमें शिशु रोग, हृदय रोग और स्त्री रोग विशेषज्ञ निःशुल्क परामर्श देंगे. निःशुल्क बुनियादी दवाएं भी वितरित की जाएंगी.',
      'n5_source': 'प्राथमिक स्वास्थ्य केंद्र (PHC)',

      // Mock Notice 6: Education
      'n6_title': 'छात्रवृत्ति आवेदन फॉर्म शुरू',
      'n6_summary': 'कक्षा 5 से 10 के छात्रों के छात्रवृत्ति आवेदन 15 सितंबर तक जमा करें.',
      'n6_desc': 'कक्षा 5 से 10 में पढ़ने वाले छात्रों को सूचित किया जाता है कि शैक्षणिक वर्ष 2026-27 के लिए प्री-मैट्रिक छात्रवृत्ति के आवेदन शुरू हो गए हैं. ग्राम पंचायत डिजिटल केंद्र में ऑनलाइन आवेदन निःशुल्क जमा किए जा सकते हैं. आवश्यक दस्तावेज: पिछली कक्षा की मार्कशीट, जाति प्रमाण पत्र और पालकों का आय प्रमाण पत्र.',
      'n6_source': 'जि. प. हाई स्कूल प्रधानाध्यापक',

      // Mock Notice 7: Events
      'n7_title': 'ग्राम सभा बैठक की सूचना',
      'n7_summary': 'शनिवार, 5 सितंबर को सुबह 10 बजे पंचायत भवन में मासिक ग्राम सभा.',
      'n7_desc': 'सूचित किया जाता है कि शनिवार, 5 सितंबर को सुबह 10:00 बजे ग्राम पंचायत सभागार में मासिक ग्राम सभा का आयोजन किया गया है. मुख्य विषय: 1. स्वच्छता कार्ययोजना की मंजूरी. 2. सड़कों की मरम्मत के लिए बजट आवंटन. 3. नए राशन कार्ड आवेदनों की समीक्षा. सभी ग्रामीणों की उपस्थिति आवश्यक है.',
      'n7_source': 'सरपंच / ग्राम सेवक कार्यालय',

