      'read_time': 'मिनट पढ़ने का समय',
      'news1_headline': 'ढवळपुरी की विभिन्न वाडियों के लिए सौर ऊर्जा जल पम्पिंग परियोजना स्वीकृत',
      'news1_summary': 'पारनेर तालुका प्रशासन द्वारा ढवळपुरी की ऊंचाई वाली वाडियों में नियमित पेयजल आपूर्ति के लिए ३ सोलर पंप सेट लगाने की मंजूरी।',
      'news1_body': 'ग्रामीण नवीकरणीय ऊर्जा और पेयजल अधोसंरचना पहल के तहत, पारनेर पंचायत समिति और ढवळपुरी ग्राम पंचायत के प्रयासों से समर्पित सौर जल उत्थान योजना को मंजूरी मिली है।\\n\\nमारुति गली, मालवाड़ी और खंडोबा बस्ती जैसे ऊंचाई वाले क्षेत्रों में गर्मी के दिनों में आने वाली पानी की समस्या का इससे स्थायी समाधान होगा। इस परियोजना में मौजूदा जलाशय से जुड़े तीन ५-हॉर्सपावर के सोलर सबमर्सिबल पंप लगाए जाएंगे।\\n\\nग्राम पंचायत अधिकारियों ने पुष्टि की कि महावितरण और जलापूर्ति विभाग के तकनीकी निरीक्षण के बाद अगले महीने काम शुरू होगा। इससे गाँव के पम्पिंग बिजली बिल में लगभग ४० प्रतिशत की कमी आएगी।',
      'news1_author': 'किशोर घोलप (ग्राम विकास संवाददाता)',
      'news1_publisher': 'ढवळपुरी ग्राम समाचार',
      'news2_headline': 'खरीफ सीजन के लिए ढवळपुरी उप-केंद्र पर जैविक खाद व बीज वितरण',
      'news2_summary': 'तालुका कृषि विभाग द्वारा ढवळपुरी के १५० से अधिक किसानों को रियायती दरों पर जैविक खाद एवं मृदा स्वास्थ्य कार्ड वितरित।',
      'news2_body': 'पारनेर कृषि विभाग और ढवळपुरी शेतकरी बचत गट के संयुक्त तत्वावधान में गाँव के कृषि उप-केंद्र पर दो दिवसीय वितरण शिविर संपन्न हुआ।\\n\\nशिविर में बाजरा व प्याज की फसलों के लिए उपयोगी ट्राइकोडर्मा, राइजोबियम जैसी जैव उर्वरक रियायती दरों पर दिए गए। साथ ही १५० से अधिक किसानों को मृदा स्वास्थ्य कार्ड बांटे गए। कृषि अधिकारियों ने जैविक खाद बनाने का व्यावहारिक प्रदर्शन भी किया।\\n\\nकिसानों से आगामी सीजन में ड्रिप सिंचाई सब्सिडी का लाभ लेने के लिए महाडीबीटी पोर्टल पर पंजीकरण कराने का अनुरोध किया गया।',
      'news2_author': 'संतोष गावडे (कृषि सहायक)',
      'news2_publisher': 'कृषि वार्ता पारनेर',
      'news3_headline': 'जिला परिषद प्राथमिक विद्यालय ढवळपुरी के छात्रों ने तालुका विज्ञान प्रतियोगिता जीती',
      'news3_summary': 'ड्रिप सिंचाई मॉडल प्रस्तुत करने वाले ढवळपुरी स्कूल के कक्षा ७ के छात्रों ने पारनेर तालुका विज्ञान प्रदर्शनी में प्रथम स्थान प्राप्त किया।',
      'news3_body': 'पारनेर में आयोजित तालुकास्तरीय ग्रामीण विज्ञान एवं नवाचार प्रदर्शनी में जिला परिषद प्राथमिक विद्यालय ढवळपुरी के छात्रों ने प्रथम स्थान प्राप्त कर गाँव का मान बढ़ाया।\\n\\nविज्ञान शिक्षक श्री दरेकर के मार्गदर्शन में कक्षा ७ के छात्र आरव ठुबे और स्नेहा शिंदे ने स्वचालित नमी संवेदक (सॉइल मॉइस्चर सेंसर) आधारित ड्रिप सिंचाई प्रणाली का कार्यशील मॉडल प्रस्तुत किया।\\n\\nइस परियोजना को अगले महीने अहिल्यानगर में होने वाली जिला विज्ञान प्रदर्शनी के लिए चुना गया है। स्कूल प्रबंधन समिति और ग्राम पंचायत ने छात्रों को बधाई दी और शैक्षणिक प्रोत्साहन अनुदान की घोषणा की।',
      'news3_author': 'सुनीता शिंदे (शिक्षा संवाददाता)',
      'news3_publisher': 'ढवळपुरी शिक्षण संवाद',
      'news4_headline': 'ग्रामसभा में स्वच्छ एवं प्लास्टिक मुक्त ढवळपुरी का सर्वसम्मत प्रस्ताव पारित',
      'news4_summary': 'सरपंच की अध्यक्षता में आयोजित विशेष ग्रामसभा में एकल-उपयोग प्लास्टिक पर प्रतिबंध और कचरा पृथक्करण का निर्णय।',
      'news4_body': 'ढवळपुरी ग्राम पंचायत भवन में सरपंच की अध्यक्षता में ग्रामीणों, युवा मंडलों और महिला स्वयं सहायता समूहों की उपस्थिति में विशेष ग्रामसभा का आयोजन किया गया।\\n\\nसभा में सर्वसम्मति से अगले माह से ढवळपुरी को एकल-उपयोग प्लास्टिक से मुक्त करने का प्रस्ताव पारित किया गया। गाँव की सभी दुकानों में कपड़े के थैलों का उपयोग करने की अपील की गई है और मुख्य बस्तियों व साप्ताहिक बाजार के लिए अलग-अलग कचरा संग्रहण प्रणाली शुरू की जाएगी।\\n\\nसरपंच रमेश ठुबे ने सभी दुकानदारों, प्याज व्यापारियों और ग्रामीणों से ढवळपुरी को पारनेर तालुका का एक आदर्श हरा-भरा गाँव बनाने में सहयोग करने का आग्रह किया।',
      'news4_author': 'ग्राम पंचायत मीडिया सेल',
      'news4_publisher': 'ढवळपुरी पंचायत रिकॉर्ड',
      'news5_headline': 'ढवळपुरी प्राथमिक स्वास्थ्य केंद्र पर निःशुल्क नेत्र जांच एवं स्वास्थ्य शिविर',
      'news5_summary': '२२० से अधिक ग्रामीणों की निःशुल्क स्वास्थ्य जांच; वरिष्ठ नागरिकों को मुफ्त चश्मे व दवाओं का वितरण किया गया।',
      'news5_body': 'अहिल्यानगर जिला अस्पताल और पारनेर ग्रामीण अस्पताल के सहयोग से ढवळपुरी प्राथमिक स्वास्थ्य केंद्र पर व्यापक निःशुल्क स्वास्थ्य जांच शिविर आयोजित हुआ।\\n\\nशिविर में २२६ ग्रामीणों की रक्तचाप, मधुमेह, ईसीजी और आँखों की जांच की गई। मोतियाबिंद से पीड़ित ३८ वरिष्ठ नागरिकों को निःशुल्क सर्जरी के लिए पंजीकृत किया गया, जिसके लिए वाहन की व्यवस्था समिति द्वारा की जाएगी।\\n\\nचिकित्सा अधिकारी डॉ. कुलकर्णी ने बताया कि हर महीने के पहले गुरुवार को ढवळपुरी पीएचसी में विशेष फॉलो-अप ओपीडी जारी रहेगी।',
      'news5_author': 'डॉ. एस. कुलकर्णी (चिकित्सा अधिकारी)',
      'news5_publisher': 'पारनेर आरोग्य पत्रिका',
      'news6_headline': 'ढवळपुरी में प्राचीन मंदिर स्थापत्य एवं शिलालेखों का दस्तावेजीकरण पूर्ण',
      'news6_summary': 'गाँव की ऐतिहासिक धरोहर को सहेजने के लिए पुराने मंदिर परिसर की पाषाण कला और बावड़ियों का दस्तावेजीकरण।',
      'news6_body': 'इतिहासकारों और शोधकर्ताओं के एक दल ने ढवळपुरी का दौरा कर मध्यकालीन पाषाण नक्काशी, वीरगलों और प्राचीन सीढ़ीदार कुओं (बावड़ियों) का अध्ययन व छायांकन किया।\\n\\nगाँव के बुजुर्गों ने शोधकर्ताओं को प्राचीन मंदिरों के ऐतिहासिक महत्व और मौखिक लोक परंपराओं की विस्तृत जानकारी दी।\\n\\nढवळपुरी की इस सांस्कृतिक धरोहर को संरक्षित करने और ग्रामीण पर्यटन को बढ़ावा देने के लिए महाराष्ट्र पुरातत्व धरोहर रजिस्टर में दर्ज करने हेतु रिपोर्ट तैयार की जा रही है।',
      'news6_author': 'प्रो. वी. देशमुख (इतिहासकार)',
      'news6_publisher': 'महाराष्ट्र हेरिटेज फोरम',
      'news_report_issue': 'गलत जानकारी रिपोर्ट करें',
